def f(gi):
    from collections import Counter
    H,W=len(gi),len(gi[0])
    vals=[x for r in gi for x in r if x!=2]
    bg=Counter(vals).most_common(1)[0][0]
    col2=None;row2=None
    for c in range(W):
        if all(gi[r][c]==2 for r in range(H)): col2=c; break
    for r in range(H):
        if any(gi[r][c]==2 for c in range(W)): row2=r; break
    vert=(col2 is not None)
    cells=[(r,c) for r in range(H) for c in range(W) if gi[r][c]!=bg and gi[r][c]!=2]
    left=[c for (r,c) in cells if c<col2]; right=[c for (r,c) in cells if c>col2]
    side='L' if left else 'R'
    out=[row[:] for row in gi]
    # bounding box of shape relative to wall, stamp adjacent on other side
    if vert:
        top,bot=min(r for r,c in cells),max(r for r,c in cells)
        L,R_=min(left),max(right)
        w=R_-L+1
        start = col2-1-w if side=='L' else col2+1
        h=bot-top+1
        for dr in range(h):
            for dc in range(w):
                val=gi[top+dr][L+dc]
                if 0<=top+dr<H and 0<=start+dc<W:
                    out[top+dr][start+dc]=val
        for r in range(top,bot+1):
            for dc in range(W):
                if gi[r][dc]==2: out[r][dc]=8
    else:
        left_,right_=min(c for r,c in cells),max(c for r,c in cells)
        t,b=min(r for r,c in cells),max(r for r,c in cells)
        h=b-t+1
        w=right_-left_+1
        start = row2-1-h if side=='U' else row2+1
        for dc in range(w):
            for dr in range(h):
                val=gi[t+dr][left_+dc]
                if 0<=t+dr<H and 0<=start+dc<W:
                    out[t+dr][start+dc]=val
        for dc in range(left_,right_+1):
            for r in range(H):
                if gi[r][dc]==2: out[r][dc]=8
    return out
